import { http, HttpResponse } from 'msw';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';

import type {
  ReviewCase,
  ReviewQueuePage,
  ReviewQueueModeTotals,
} from '../../src/routes/review/-review.api';

import { shellHandlers } from '../visual/fixtures';

/** Generated by the real Python scan/queue tests, never hand-authored UI states. */
export function acceptanceSnapshot(name: string): {
  case: ReviewCase;
  queue: ReviewQueuePage;
  summary: ReviewQueueModeTotals;
  finding_types: unknown[];
  ready_preview: {
    signature: string;
    action_count: number;
    file_actions: number;
    albums: unknown[];
  };
} {
  return JSON.parse(
    readFileSync(resolve('tests/fixtures/review-acceptance', `${name}.json`), 'utf8'),
  );
}

export function acceptanceApi(initial: string) {
  let snapshot = acceptanceSnapshot(initial);
  const unexpected: string[] = [];
  return {
    get current() {
      return snapshot.case;
    },
    setCase(name: string) {
      snapshot = acceptanceSnapshot(name);
    },
    unexpected,
    handlers: [
      ...shellHandlers,
      http.get('*/api/repair/review-queue/summary', () => HttpResponse.json(snapshot.summary)),
      http.get('*/api/repair/review-queue', () => HttpResponse.json(snapshot.queue)),
      http.get('*/api/repair/review-queue/apply-ready', () =>
        HttpResponse.json(snapshot.ready_preview),
      ),
      http.get('*/api/repair/review-queue/:id', () => HttpResponse.json(snapshot.case)),
      http.get('*/api/repair/finding-types', () =>
        HttpResponse.json({ types: snapshot.finding_types }),
      ),
      http.get('*/api/repair/status', () => HttpResponse.json({ current_job: null })),
      http.get('*/api/repair/history', () => HttpResponse.json({ runs: [] })),
      http.get('*/api/repair/bulk-fix/status', () => HttpResponse.json({ running: false })),
      http.post('*/api/library/album/:id/reorganize/preview', () =>
        HttpResponse.json({ success: true, tracks: [] }),
      ),
      http.all('*/api/repair/*', ({ request }) => {
        unexpected.push(`${request.method} ${new URL(request.url).pathname}`);
        return HttpResponse.json({ error: 'Unexpected acceptance request' }, { status: 501 });
      }),
    ],
  };
}
